    notes: { tip: 'Box model, specificity, flex vs grid — ye 3 pakka aate hain.', concept: '"Kyun" samjho, ratta nahi.', warning: 'Live coding mein centering aur responsive layout aana chahiye.' },
    summary: ['Beginner: box model, selectors, position, display.', 'Intermediate: flex/grid, units, specificity, responsive.', 'Advanced: stacking context, reflow/repaint, BFC, critical CSS.'],
